```python
import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult

def extract_receipt_data(receipt_url: str) -> dict:
    """
    Extracts merchant, tax, total, and items from a receipt using Azure AI Document Intelligence.

    This function requires the following environment variables to be set:
    - AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT: The endpoint of your Document Intelligence resource.
    - AZURE_DOCUMENT_INTELLIGENCE_KEY: The API key for your Document Intelligence resource.

    :param receipt_url: The public URL of the receipt image or PDF to analyze.
    :return: A dictionary containing the extracted receipt data.
    """
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    # Use the pre-built receipt model
    poller = document_intelligence_client.begin_analyze_document(
        "prebuilt-receipt", analyze_request={"urlSource": receipt_url}
    )
    result: AnalyzeResult = poller.result()

    extracted_data = {}

    if not result.documents:
        return extracted_data

    # Assuming the first document in the result is the receipt
    receipt = result.documents[0]

    # Extract merchant name
    merchant_field = receipt.fields.get("MerchantName")
    if merchant_field and merchant_field.content:
        extracted_data["merchant"] = merchant_field.content

    # Extract total tax
    tax_field = receipt.fields.get("TotalTax")
    if tax_field:
        if tax_field.value_currency:
            extracted_data["tax"] = tax_field.value_currency.amount
        else:
            extracted_data["tax"] = tax_field.content

    # Extract total
    total_field = receipt.fields.get("Total")
    if total_field:
        if total_field.value_currency:
            extracted_data["total"] = total_field.value_currency.amount
        else:
            extracted_data["total"] = total_field.content

    # Extract line items
    items_field = receipt.fields.get("Items")
    if items_field and items_field.value_array:
        items_list = []
        for item_field in items_field.value_array:
            item_details = {}
            if item_field.value_object:
                # Description
                desc_field = item_field.value_object.get("Description")
                if desc_field and desc_field.content:
                    item_details["description"] = desc_field.content

                # Total price of the line item
                price_field = item_field.value_object.get("TotalPrice")
                if price_field:
                    if price_field.value_currency:
                        item_details["total_price"] = price_field.value_currency.amount
                    else:
                        item_details["total_price"] = price_field.content

            if item_details:
                items_list.append(item_details)

        if items_list:
            extracted_data["items"] = items_list

    return extracted_data
